#nullable enable // autogenerated

using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Enemies;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Pickups;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Models;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.loanSign)]
    public class LoanSign : AIEntityBehaviour
    {
        public LoanSign(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            var lendCount = GetLendCount(entity);
            for (int i = 0; i < lendCount; i++)
            {
                entity.ProduceStarshard(entity.GetCenter());
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);

            var maxSeconds = entity.GetProperty<float>(PROP_MAX_CREAKING_SECONDS);
            var timer = GetCreakingTimer(entity);
            if (timer == null)
            {
                timer = TimerHelper.NewSecondTimer(maxSeconds);
                SetCreakingTimer(entity, timer);
            }

            if (!entity.Level.IsAllEnemiesCleared())
            {
                if (timer.RunToExpired())
                {
                    var multiplier = entity.GetProperty<float>(PROP_SECONDS_MULTIPLIER_PER_SPAWN);
                    var minSeconds = entity.GetProperty<float>(PROP_MIN_CREAKING_SECONDS);
                    float seconds = timer.GetMaxSeconds();
                    seconds = Mathf.Clamp(seconds * multiplier, minSeconds, maxSeconds);
                    timer.ResetSeconds(seconds);

                    SpawnCreakingAtRandomLane(entity);
                }
            }

            var timePercent = timer?.GetPassedPercentage() ?? 0;
            var flower1 = Mathf.FloorToInt(Mathf.Clamp(timePercent * FLOWER_TOTAL_STATES, 0, FLOWER_STATES));
            var flower2 = Mathf.FloorToInt(Mathf.Clamp(timePercent * FLOWER_TOTAL_STATES - FLOWER_STATES, 0, FLOWER_STATES));
            var flower3 = Mathf.FloorToInt(Mathf.Clamp(timePercent * FLOWER_TOTAL_STATES - 2 * FLOWER_STATES, 0, FLOWER_STATES));
            entity.SetModelProperty("RepaidCount", GetRepaidCount(entity));
            entity.SetModelProperty("Flower1", flower1);
            entity.SetModelProperty("Flower2", flower2);
            entity.SetModelProperty("Flower3", flower3);
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            var repayCount = GetRepaidCount(entity);
            if (repayCount < GetMaxRepayCount(entity))
            {
                SpawnCreakingColumn(entity);
            }
        }
        public static void Repay(Entity entity, int count = 1)
        {
            int value = GetRepaidCount(entity) + count;
            SetRepaidCount(entity, value);
            if (value >= GetMaxRepayCount(entity))
            {
                entity.SpawnWithParams(VanillaEffectID.smokeCluster, entity.GetCenter());
                entity.Remove();
            }
        }
        public static void ResetCreakingTime(Entity entity)
        {
            var maxSeconds = entity.GetProperty<float>(PROP_MAX_CREAKING_SECONDS);
            var timer = GetCreakingTimer(entity);
            if (timer == null)
            {
                timer = TimerHelper.NewSecondTimer(maxSeconds);
                SetCreakingTimer(entity, timer);
            }
            else
            {
                timer.ResetSeconds(maxSeconds);
            }
        }
        public static void SpawnCreakingColumn(Entity entity)
        {
            var level = entity.Level;
            for (int i = 0; i < level.GetMaxLaneCount(); i++)
            {
                SpawnCreaking(entity, i);
            }
        }
        public static Entity? SpawnCreaking(Entity entity, int lane)
        {
            entity.PlaySound(VanillaSoundID.creakingSpawn);

            var level = entity.Level;
            var entityDef = level.Content.GetEntityDefinition(VanillaEnemyID.creaking);
            if (entityDef != null)
            {
                var x = level.GetEnemySpawnX();
                var z = level.GetEntityLaneZ(lane);
                var y = level.GetGroundY(x, z);
                var pos = new Vector3(x, y, z) + entityDef.GetStartingPositionOffset();
                var creaking = level.Spawn(entityDef, pos, entity);
                if (creaking != null)
                {
                    var param = entity.GetSpawnParams();
                    param.SetProperty(CreakingParticles.PROP_SOURCE_POSITION, entity.GetCenter());
                    param.SetProperty(CreakingParticles.PROP_TARGET_POSITION, creaking.GetCenter());
                    entity.Spawn(VanillaEffectID.creakingParticles, entity.GetCenter(), param);
                }
                ;
                return creaking;
            }
            return null;
        }
        public static Entity? SpawnCreakingAtRandomLane(Entity entity)
        {
            int lane;
            var creakingSpawn = entity.Level.Content.GetSpawnDefinition(VanillaSpawnID.creaking);
            if (creakingSpawn != null)
            {
                lane = creakingSpawn.GetRandomSpawnLane(entity.Level);
            }
            else
            {
                lane = entity.Level.GetRandomEnemySpawnLane();
            }
            return SpawnCreaking(entity, lane);
        }
        public static int GetLendCount(Entity entity) => entity.GetBehaviourField<int>(PROP_LEND_COUNT);
        public static void SetLendCount(Entity entity, int value) => entity.SetBehaviourField(PROP_LEND_COUNT, value);
        public static int GetMaxRepayCount(Entity entity) => entity.GetBehaviourField<int>(PROP_MAX_REPAY_COUNT);
        public static void SetMaxRepayCount(Entity entity, int value) => entity.SetBehaviourField(PROP_MAX_REPAY_COUNT, value);
        public static int GetRepaidCount(Entity entity) => entity.GetBehaviourField<int>(PROP_REPAID_COUNT);
        public static void SetRepaidCount(Entity entity, int value) => entity.SetBehaviourField(PROP_REPAID_COUNT, value);
        public static FrameTimer? GetCreakingTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(PROP_CREAKING_TIMER);
        public static void SetCreakingTimer(Entity entity, FrameTimer? value) => entity.SetBehaviourField(PROP_CREAKING_TIMER, value);
        public static readonly VanillaEntityPropertyMeta<int> PROP_LEND_COUNT = new VanillaEntityPropertyMeta<int>("lend_count", 2);
        public static readonly VanillaEntityPropertyMeta<int> PROP_MAX_REPAY_COUNT = new VanillaEntityPropertyMeta<int>("max_repay_count", 2);
        public static readonly VanillaEntityPropertyMeta<int> PROP_REPAID_COUNT = new VanillaEntityPropertyMeta<int>("repaied_count");
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_CREAKING_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("creaking_timer");
        public static readonly VanillaEntityPropertyMeta<float> PROP_MAX_CREAKING_SECONDS = new VanillaEntityPropertyMeta<float>("max_creaking_seconds", 120f);
        public static readonly VanillaEntityPropertyMeta<float> PROP_MIN_CREAKING_SECONDS = new VanillaEntityPropertyMeta<float>("min_creaking_seconds", 15f);
        public static readonly VanillaEntityPropertyMeta<float> PROP_SECONDS_MULTIPLIER_PER_SPAWN = new VanillaEntityPropertyMeta<float>("seconds_multiplier_per_spawn", 0.5f);

        public const int FLOWER_STATES = 2;
        public const int FLOWER_COUNT = 3;
        public const int FLOWER_TOTAL_STATES = FLOWER_STATES * FLOWER_COUNT;
    }
}
